library(dplyr)
library(ggplot2)
library(readr)
library(stringr)
library(UlavalSSD)

condamnations &lt;- listecondamnation |&gt;
  mutate(
    amende_num = parse_number(Amende, locale = locale(grouping_mark = " ")),
    ville_montreal = str_detect(Adresse_lieu_infraction, regex("MONTREAL|MONTRÉAL", ignore_case = TRUE))
  )

condamnations |&gt;
  count(Type_etablissement, sort = TRUE) |&gt;
  slice_head(n = 8)

condamnations |&gt;
  filter(!is.na(amende_num)) |&gt;
  group_by(Type_etablissement) |&gt;
  summarise(
    n = n(),
    amende_mediane = median(amende_num),
    .groups = "drop"
  ) |&gt;
  arrange(desc(n))

